    propensityMethod = "auto",
    minPS = 0.01,
    maxPS = 0.99,
    bootstrapSamples = 0,
    randomSeed = 24680,
    confidenceLevel = 95,
    effectMeasure = "riskDifference",
    showFlowPlot = TRUE,
    showBalancePlot = TRUE,
    showEffectPlot = TRUE,
    showSyntax = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("landmarkTrial requires jmvcore to be installed (restart may be required)")

    if ( ! missing(eligibility)) eligibility <- jmvcore::resolveQuo(jmvcore::enquo(eligibility))
    if ( ! missing(treatmentA)) treatmentA <- jmvcore::resolveQuo(jmvcore::enquo(treatmentA))
    if ( ! missing(treatmentB)) treatmentB <- jmvcore::resolveQuo(jmvcore::enquo(treatmentB))
    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(failureEvent1)) failureEvent1 <- jmvcore::resolveQuo(jmvcore::enquo(failureEvent1))
    if ( ! missing(failureEvent2)) failureEvent2 <- jmvcore::resolveQuo(jmvcore::enquo(failureEvent2))
    if ( ! missing(competingEvent)) competingEvent <- jmvcore::resolveQuo(jmvcore::enquo(competingEvent))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if ( ! missing(indexTime)) indexTime <- jmvcore::resolveQuo(jmvcore::enquo(indexTime))
    if ( ! missing(treatmentATime)) treatmentATime <- jmvcore::resolveQuo(jmvcore::enquo(treatmentATime))
    if ( ! missing(treatmentBTime)) treatmentBTime <- jmvcore::resolveQuo(jmvcore::enquo(treatmentBTime))
    if ( ! missing(failureTime1)) failureTime1 <- jmvcore::resolveQuo(jmvcore::enquo(failureTime1))
    if ( ! missing(failureTime2)) failureTime2 <- jmvcore::resolveQuo(jmvcore::enquo(failureTime2))
    if ( ! missing(dischargeTime)) dischargeTime <- jmvcore::resolveQuo(jmvcore::enquo(dischargeTime))
    if ( ! missing(competingTime)) competingTime <- jmvcore::resolveQuo(jmvcore::enquo(competingTime))
    if ( ! missing(covariates)) covariates <- jmvcore::resolveQuo(jmvcore::enquo(covariates))
    if ( ! missing(absenceVars)) absenceVars <- jmvcore::resolveQuo(jmvcore::enquo(absenceVars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(eligibility), eligibility, NULL),
            `if`( ! missing(treatmentA), treatmentA, NULL),
            `if`( ! missing(treatmentB), treatmentB, NULL),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(failureEvent1), failureEvent1, NULL),
            `if`( ! missing(failureEvent2), failureEvent2, NULL),
            `if`( ! missing(competingEvent), competingEvent, NULL),
            `if`( ! missing(cluster), cluster, NULL),
            `if`( ! missing(indexTime), indexTime, NULL),
            `if`( ! missing(treatmentATime), treatmentATime, NULL),
            `if`( ! missing(treatmentBTime), treatmentBTime, NULL),
            `if`( ! missing(failureTime1), failureTime1, NULL),
            `if`( ! missing(failureTime2), failureTime2, NULL),
            `if`( ! missing(dischargeTime), dischargeTime, NULL),
            `if`( ! missing(competingTime), competingTime, NULL),
            `if`( ! missing(covariates), covariates, NULL),
            `if`( ! missing(absenceVars), absenceVars, NULL))


    options <- landmarkTrialOptions$new(
        eligibility = eligibility,
        treatmentA = treatmentA,
        treatmentB = treatmentB,
        outcome = outcome,
        failureEvent1 = failureEvent1,
        failureEvent2 = failureEvent2,
        competingEvent = competingEvent,
        cluster = cluster,
        indexTime = indexTime,
        treatmentATime = treatmentATime,
        treatmentBTime = treatmentBTime,
        failureTime1 = failureTime1,
        failureTime2 = failureTime2,
        dischargeTime = dischargeTime,
        competingTime = competingTime,
        covariates = covariates,
        absenceVars = absenceVars,
        eligibilityPositive = eligibilityPositive,
        treatmentAPositive = treatmentAPositive,
        treatmentBPositive = treatmentBPositive,
        outcomePositive = outcomePositive,
        outcomeSource = outcomeSource,
        competingHandling = competingHandling,
        timeMode = timeMode,
        timeUnit = timeUnit,
        window1 = window1,
        runSecondWindow = runSecondWindow,
        window2 = window2,
        unknownTreatment = unknownTreatment,
        unknownEvent = unknownEvent,
        runBothStrata = runBothStrata,
        primaryStratum = primaryStratum,
        primaryWindow = primaryWindow,
        missingMethod = missingMethod,
        imputations = imputations,
        outcomeMethod = outcomeMethod,
        propensityMethod = propensityMethod,
        minPS = minPS,
        maxPS = maxPS,
        bootstrapSamples = bootstrapSamples,
        randomSeed = randomSeed,
        confidenceLevel = confidenceLevel,
        effectMeasure = effectMeasure,
        showFlowPlot = showFlowPlot,
        showBalancePlot = showBalancePlot,
        showEffectPlot = showEffectPlot,
        showSyntax = showSyntax)

    analysis <- landmarkTrialClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

